(() => {
  class BeatDashRenderer {
    constructor(canvas, config){this.canvas=canvas;this.ctx=canvas.getContext('2d');this.config=config;this.dpr=1;this.width=0;this.height=0;this.particles=new window.ArcadeParticles();this.shake=0;this.resize()}
    resize(){this.dpr=Math.min(devicePixelRatio||1,2);this.width=innerWidth;this.height=innerHeight;this.canvas.width=Math.round(this.width*this.dpr);this.canvas.height=Math.round(this.height*this.dpr);this.ctx.setTransform(this.dpr,0,0,this.dpr,0,0)}
    reset(){this.particles.clear();this.shake=0}
    emit(x,y,color,count=12){this.particles.spawn(x,y,color,count)}
    visual(slot=null){return window.TelePlayShop?.visualForGame?.('beat-dash',slot)||{color:'#65efff',accent:'#a779ff'}}
    fade(value,alpha=1){const raw=String(value||'').replace('#','');if(raw.length!==6)return value;const n=parseInt(raw,16);return `rgba(${n>>16},${(n>>8)&255},${n&255},${alpha})`}
    render(snapshot){const c=this.ctx,w=this.width,h=this.height,s=Math.min(w/390,1.25),ground=h*.72,px=112*s,now=performance.now()/1000;this.particles.update(.016);
      c.save();if(this.shake>0){c.translate((Math.random()-.5)*this.shake,(Math.random()-.5)*this.shake);this.shake*=.88}
      const theme=this.visual('world-themes'),bg=c.createLinearGradient(0,0,0,h);bg.addColorStop(0,this.fade(theme.accent,.34));bg.addColorStop(.55,this.fade(theme.color,.16));bg.addColorStop(1,'#050611');c.fillStyle=bg;c.fillRect(0,0,w,h);
      this.drawCity(c,w,h,s,snapshot.elapsed);this.drawGrid(c,w,h,s,ground,snapshot.worldX);
      for(const gap of this.config.obstacles.filter(o=>o.type==='gap')){const x=px+(gap.x-snapshot.worldX)*s;c.fillStyle='#040511';c.fillRect(x,ground-4,gap.width*s,10);c.strokeStyle='#ff54b7';c.shadowColor='#ff54b7';c.shadowBlur=12;c.lineWidth=2;c.beginPath();c.moveTo(x,ground);c.lineTo(x+gap.width*s,ground);c.stroke();c.shadowBlur=0}
      for(const obstacle of this.config.obstacles){const x=px+(obstacle.x-snapshot.worldX)*s;if(x<-100||x>w+100)continue;this.drawObstacle(c,obstacle,x,ground,s,snapshot.elapsed)}
      for(const coin of this.config.coins){if(coin.collected)continue;const x=px+(coin.x-snapshot.worldX)*s;if(x<-50||x>w+50)continue;this.drawCoin(c,x,ground-coin.y*s,s,now,coin.risk==='risk')}
      this.drawRunnerTrail(c,px,ground-snapshot.playerY*s,s,snapshot,now);this.drawParticles(c);this.drawCore(c,px,ground-snapshot.playerY*s,s,snapshot,now);c.restore();
    }
    drawCity(c,w,h,s,time){for(let i=0;i<14;i++){const x=((i*97-time*8)% (w+120))-60,bh=(35+(i*31)%100)*s;c.fillStyle=i%2?'#1d2250':'#20235b';c.fillRect(x,h*.58-bh,55*s,bh);for(let yy=h*.58-bh+12;yy<h*.58-4;yy+=17){c.fillStyle=i%2?'#4fe9ff33':'#ff62bd33';c.fillRect(x+10,yy,4,7)}}}
    drawGrid(c,w,h,s,ground,offset){c.save();c.strokeStyle='#6f69db22';c.lineWidth=1;for(let x=-40+(offset*-.35)%60;x<w+80;x+=60){c.beginPath();c.moveTo(x,ground);c.lineTo(x+w*.5+(x-w/2)*.14,h);c.stroke()}for(let y=ground;y<h;y+=30){c.beginPath();c.moveTo(0,y);c.lineTo(w,y);c.stroke()}c.strokeStyle='#49eaff88';c.shadowColor='#49eaff';c.shadowBlur=14;c.lineWidth=3;c.beginPath();c.moveTo(0,ground);c.lineTo(w,ground);c.stroke();c.restore()}
    drawObstacle(c,o,x,ground,s,time){c.save();c.shadowBlur=18;c.shadowColor=o.type==='timing'?'#ff54b7':'#9369ff';if(o.type==='spike'){c.fillStyle='#ff54b7';c.beginPath();c.moveTo(x,ground);c.lineTo(x+o.width*s/2,ground-o.height*s);c.lineTo(x+o.width*s,ground);c.closePath();c.fill();c.strokeStyle='#ffd0f0';c.stroke()}if(o.type==='moving'){const y=ground-(o.baseY+Math.sin(time*o.frequency)*o.amplitude)*s-o.height*s;c.fillStyle='#9369ff';c.fillRect(x,y,o.width*s,o.height*s);c.strokeStyle='#b8faff';c.strokeRect(x,y,o.width*s,o.height*s);c.fillStyle='#ff54b766';c.fillRect(x-18*s,y+o.height*s/2-2,(o.width+36)*s,4)}if(o.type==='timing'){c.strokeStyle='#ff54b7';c.lineWidth=6;c.beginPath();c.moveTo(x,ground);c.lineTo(x,ground-o.height*s);c.moveTo(x+o.width*s,ground);c.lineTo(x+o.width*s,ground-o.height*s);c.stroke();c.strokeStyle='#6ff4ff';c.lineWidth=4;c.beginPath();c.moveTo(x,ground-o.windowMin*s);c.lineTo(x+o.width*s,ground-o.windowMin*s);c.stroke();c.fillStyle='#ff54b7';c.globalAlpha=.45;c.fillRect(x,ground-o.windowMax*s,o.width*s,(o.windowMax-o.windowMin)*s);c.globalAlpha=1}c.restore()}
    drawCoin(c,x,y,s,time,risk){c.save();c.translate(x,y);c.scale(.65+Math.abs(Math.cos(time*5))*.35,1);c.shadowColor=risk?'#ff54b7':'#ffd45b';c.shadowBlur=15;c.fillStyle=risk?'#ff72c7':'#ffd45b';c.beginPath();c.arc(0,0,10*s,0,Math.PI*2);c.fill();c.strokeStyle='#fff1a7';c.lineWidth=2;c.stroke();c.fillStyle='#fff';c.font=`900 ${9*s}px system-ui`;c.textAlign='center';c.fillText('₵',0,3*s);c.restore()}
    drawRunnerTrail(c,x,y,s,snapshot,time){const item=window.TelePlayShop?.equippedForGame?.('beat-dash','trails'),trail=item?.visual||item?.visualData;if(!trail)return;c.save();c.globalAlpha=.3;c.shadowColor=trail.color;c.shadowBlur=18;for(let i=1;i<5;i++){c.fillStyle=i%2?trail.color:trail.accent;c.beginPath();c.arc(x-i*10*s,y+i*3*s,Math.max(2,7-i)*s,0,Math.PI*2);c.fill()}c.restore()}
    drawCore(c,x,y,s,snapshot,time){c.save();const visual=this.visual('runner-style'),effectItem=window.TelePlayShop?.equippedForGame?.('beat-dash','effects'),effect=effectItem?.visual||effectItem?.visualData,pulse=1+Math.sin(time*6)*.06;const core=snapshot.state==='dead'?Math.max(.2,snapshot.elapsed%1):1;c.translate(x,y);c.rotate(Math.max(-.15,Math.min(.15,snapshot.velocityY/5000)));c.globalAlpha=core;c.shadowColor=effect?.color||visual.color;c.shadowBlur=effect?36:28;c.fillStyle=visual.color;c.beginPath();c.arc(0,0,18*s*pulse,0,Math.PI*2);c.fill();c.shadowBlur=0;c.fillStyle='#fff';c.beginPath();c.arc(-5*s,-5*s,5*s,0,Math.PI*2);c.fill();c.strokeStyle=effect?.accent||visual.accent;c.lineWidth=3;c.beginPath();c.arc(0,0,27*s,0,Math.PI*2);c.stroke();c.restore()}
    drawParticles(c){this.particles.render(c)}
  }
  window.BeatDashRenderer=BeatDashRenderer;
})();
